require __DIR__.'/../../config.php';if(DB_NAME!=='maakit_jaanch')throw new RuntimeException('CI database only');require __DIR__.'/../../school/inc.php';$db=sch_db();
function st_ok($ok,$why){if(!$ok)throw new RuntimeException('Studio: '.$why);}
function st_request($action,$token,$body=null){$c=curl_init('http://127.0.0.1:8099/school/studio_api.php?a='.$action);$h=['X-School-Token: '.$token];$o=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_PROXY=>'',CURLOPT_TIMEOUT=>20];if($body!==null){$o[CURLOPT_POST]=true;if(is_array($body)&&isset($body['file'])&&$body['file'] instanceof CURLFile)$o[CURLOPT_POSTFIELDS]=$body;else{$h[]='Content-Type: application/json';$o[CURLOPT_POSTFIELDS]=json_encode($body);}}$o[CURLOPT_HTTPHEADER]=$h;curl_setopt_array($c,$o);$raw=curl_exec($c);$code=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);st_ok(is_string($raw)&&!preg_match('/Fatal error|Warning:|Uncaught/',$raw),'PHP warning in response');return [$code,json_decode($raw,true),$raw];}
function st_id(){return sprintf('%s-%s-%s-%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2)),bin2hex(random_bytes(6)));}
function st_token($uid,$role,$tid){$db=sch_db();$db->prepare('INSERT INTO sch_users(uid,role,tid) VALUES(?,?,?) ON DUPLICATE KEY UPDATE role=VALUES(role),tid=VALUES(tid)')->execute([$uid,$role,$tid]);$token=bin2hex(random_bytes(32));$db->prepare('INSERT INTO sch_sessions(token_hash,uid,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 DAY))')->execute([hash('sha256',$token),$uid]);return $token;}
