 [$c,$j]=st_request('upload',$A,['file'=>new CURLFile($file,'image/jpeg','copy.jpg')]);st_ok($c===200,'Private image upload failed');$image=$j['id'];$copy=st_id();$submit=['id'=>$copy,'task'=>$task,'sid'=>'studio-own','pages'=>[$image],'prepared'=>[$image]];
 [$c]=st_request('submit',$B,$submit);st_ok($c===403,'Another parent submitted for child');[$c]=st_request('submit',$A,$submit);st_ok($c===200,'Own submission failed');
 [$c]=st_request('media&id='.$image,$B);st_ok($c===403,'Other parent read notebook image');[$c]=st_request('media&id='.$image,$X);st_ok($c===403,'Wrong teacher read notebook image');[$c]=st_request('media&id='.$image,$T);st_ok($c===200,'Assigned teacher cannot read notebook');
 [$c]=st_request('ai',$A,['id'=>st_id(),'copy'=>$copy,'consent'=>true]);st_ok($c===403,'Parent triggered AI checking');
 [$c]=st_request('review',$T,['id'=>st_id(),'copy'=>$copy,'marks'=>26,'feedback'=>'Wrong total','annotations'=>[],'approved'=>true]);st_ok($c===400,'Marks over maximum accepted');
 [$c]=st_request('review',$T,['id'=>st_id(),'copy'=>$copy,'marks'=>23,'feedback'=>'Check one step','annotations'=>[['page'=>0,'x'=>.3,'y'=>.4,'type'=>'error','text'=>'Check sign']],'approved'=>true]);st_ok($c===200,'Teacher approval failed');
 [$c,$j]=st_request('state',$A);st_ok(count($j['copies'])===1&&$j['copies'][0]['review']['marks']===23&&count($j['copies'][0]['checkedPages'])===1,'Approved copy not available');[$c,$j]=st_request('state',$B);st_ok(!$j['copies'],'Other parent received copy');
 [$c]=st_request('review',$T,['id'=>st_id(),'copy'=>$copy,'marks'=>1,'feedback'=>'Overwrite','annotations'=>[],'approved'=>true]);st_ok($c===409,'Approved marks overwritten');
 $post=st_id();[$c]=st_request('post',$T,['id'=>$post,'cls'=>'4th','caption'=>'Synthetic classroom activity','media'=>[],'permission'=>true]);st_ok($c===200,'Teacher post failed');[$c,$j]=st_request('state',$B);st_ok(!$j['posts'],'Other class received feed');
 [$c]=st_request('react',$B,['id'=>st_id(),'post'=>$post,'type'=>'love']);st_ok($c===403,'Other parent reacted to private post');foreach(['love','applaud'] as $type){[$c]=st_request('react',$A,['id'=>st_id(),'post'=>$post,'type'=>$type]);st_ok($c===200,'Parent reaction failed');}[$c,$j]=st_request('state',$A);st_ok($j['posts'][0]['counts']['love']===0&&$j['posts'][0]['counts']['applaud']===1,'Reaction duplicated');
 [$c]=st_request('house',$T,['id'=>st_id(),'sid'=>'studio-own','house'=>'Tagore']);st_ok($c===403,'Teacher assigned houses');[$c]=st_request('house',$P,['id'=>st_id(),'sid'=>'studio-own','house'=>'Tagore']);st_ok($c===200,'Principal house assignment failed');
 $badge=st_id();$award=['id'=>$badge,'sid'=>'studio-own','badge'=>'star','reason'=>'Helped a classmate'];[$c]=st_request('badge',$T,$award);st_ok($c===200,'Badge failed');[$c]=st_request('badge',$T,$award);st_ok($c===200,'Retry duplicated/rejected awarded badge');$award['id']=st_id();[$c]=st_request('badge',$T,$award);st_ok($c===409,'Same-day duplicate badge accepted');[$c,$j]=st_request('state',$A);st_ok($j['houses']['Tagore']===5,'House score double counted');
 [$c]=st_request('message',$A,['id'=>st_id(),'sid'=>'studio-other','tid'=>'SX','text'=>'Wrong child']);st_ok($c===403,'Parent messaged about another child');[$c]=st_request('message',$A,['id'=>st_id(),'sid'=>'studio-own','tid'=>'ST','text'=>'Synthetic parent message']);st_ok($c===200,'Parent message failed');[$c,$j]=st_request('state',$B);st_ok(!$j['messages'],'Private chat leaked to another parent');[$c,$j]=st_request('state',$X);st_ok(!$j['messages'],'Private chat leaked to another teacher');
 [$c]=st_request('preference',$T,['id'=>st_id(),'sid'=>'studio-own','whatsapp'=>true]);st_ok($c===403,'Teacher opted parent into WhatsApp');[$c]=st_request('preference',$A,['id'=>st_id(),'sid'=>'studio-own','whatsapp'=>true]);st_ok($c===200,'Parent opt-in failed');
